head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.vScrenID = 'ULDSTF15410.xml';
scwin.gUsrId = js_id;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    //edt_FromDate.text = vCurDate; 	// 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    dts_SecuGrpID.DataID = "/DisclosureSearch.do?method=getFuturesOptionList&inputMessageId=CODE_OUT&For=R&COM_ATTR_TP_CD=";
    dts_SecuGrpID.Reset();
};
scwin.fn_myFormNmList = function() {
    // 사용자서식 명칭 리스트
    var url = "/MyFormPage.do?method=listMyFormNm&For=C" + "&USR_ID=" + scwin.gUsrId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_myFormNmList.DataID = encodeURI(url);
    dts_myFormNmList.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시상세--;
목록검색;
클릭-- > function() {
    var vFormCd = $c.stf.getObjectValue(txb_FormCd);
    var vFormNm = $c.stf.getObjectValue(txb_FormNm);

    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }

    // 보고서코그 체크
    if (vFormCd.length > 0 && vFormCd.length != 5) {
        $c.win.alert("서식코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    fn_Search();
} < !공시상세--;
클릭-- > function() {
    var edt_FromDate_year = $c.stf.getObjectValue(edt_FromDate).substr(0, 4);
    var edt_FromDate_month = $c.stf.getObjectValue(edt_FromDate).substr(4, 2) - 1;
    var edt_FromDate_day = $c.stf.getObjectValue(edt_FromDate).substr(6, 2);
    var edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    var edt_ToDate_year = $c.stf.getObjectValue(edt_ToDate).substr(0, 4);
    var edt_ToDate_month = $c.stf.getObjectValue(edt_ToDate).substr(4, 2) - 1;
    var edt_ToDate_day = $c.stf.getObjectValue(edt_ToDate).substr(6, 2);
    var edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);

    // 회사코드 조건없이 3년 이상의 기간은 검색 할 수 없다
    var company_code = $c.stf.getObjectValue(txb_isur_cd);
    var date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (!company_code && date_result > 1096) {
        $c.win.alert("검색기간 3년 이상 조회시 회사코드를 필수로 선택하여야 합니다.");
        return;
    }
    var url = "/DisclosureSearch.do?method=listFuturesOptionDsclSrch" + "&inputMessageId=FUTURERSOPTION_IN" + "&outputMessageId=FUTURERSOPTION_OUT" + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&CHECK_DERIVATIVE=" + scwin.getChkValue(chb_derivative) + "&MYFORM_LIST_GRP=" + $c.stf.getObjectValue(cmb_myFormNmList) + "&USR_ID=" + scwin.gUsrId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.getChkValue = function(obj) {
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
};
scwin.fn_UlyIsuDown = function() {
    //vComAttrTpCd = cmb_StockOrEtf.ValueOfIndex("VALUE", cmb_StockOrEtf.Index);

    dts_UlyIsuList.DataID = "/DisclosureSearch.do?method=getUlyIsuList&COM_ATTR_TP_CD=";
    dts_UlyIsuList.Reset();
    $c.data.downloadGridViewExcel(grd_UlyIsuList, "주식선물/옵션 기초자산 현황", "", "8");
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.btn_myForm_onclick = async function() {
    await $c.frame.CreateDialogFrame("gform", "/indinfo/ULDSTF51000.gfm", "사용자서식관리", 300, 100, 1300, 750, "window");
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.win.alert(dts_DsclList.errorMsg);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclList.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_SecuGrpID_OnLoadError = function() {
    $c.win.alert(dts_UlyIsuCnt.errorMsg);
};
scwin.dts_SecuGrpID_OnLoadCompleted = function(rowcount) {
    //vComAttrTpCd = cmb_StockOrEtf.ValueOfIndex("VALUE", cmb_StockOrEtf.Index);

    dts_UlyIsuCnt.DataID = "/DisclosureSearch.do?method=getUlyIsuCntTxt&inputMessageId=CODE_OUT&COM_ATTR_TP_CD=";
    dts_UlyIsuCnt.Reset();
    var ulyIsuCnt = dts_UlyIsuCnt.getCellData(dts_UlyIsuCnt.getTotalRow(), "TEXT"); //기초자산 종목수 2018.09.14

    var vTotalArea = "<a style='border:1px; border-style__dashed; padding:3; cursor:pointer;'><span style='font-size__9pt; font-family:굴림; color:#212863;'>기초자산 종목수: </span><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold;'>" + ulyIsuCnt + "</span></a>";
    panel_uly_isu.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vTotalArea + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        //2017-11-28 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "주식선물_옵션 대상자산 공시", "", "8");
};
scwin.img_FindForm_onclick = async function() {
    // *** 셋팅할 필드명 정의를 아래처럼 해야함.
    // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
    var url = "/common/ULDSTF91003_FUTURES.gfm";
    var winTitle = "공시제목선택 ";
    await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 700, 580, "window");
};
scwin.txb_FormCd_onblur = function() {
    if (txb_FormCd.getValue() == "") {
        txb_FormNm.setValue("");
    }
};
scwin.txb_FormNm_onblur = function() {
    if (txb_FormNm.getValue() == "") {
        txb_FormCd.setValue("");
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_myFormNmList_OnLoadCompleted = function(rowcount) {
    //cmd_myFormNmList.index = -1;

};
scwin.dts_myFormNmList_OnLoadError = function() {
    $c.stf.alert_error("OnLoadError => " + dts_myFormNmList);
};
scwin.panel_uly_isu_onclick = function() {
    scwin.fn_UlyIsuDown();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    //Grd_com_isur.style.display ="";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    /*
    if (window.event.keyCode == 40) {
    		//아래화살표눌렀을때 그리드로 포커스
    		Grd_com_isur.Focus();
    }else{
    	if (window.event.keyCode ==13){
    		fn_com_Confirm_set();
    	}else{
    		fn_com_isur_nm(window.event.keyCode);
    	}
    }
    */
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearchFuturesOption(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur_futures(txb_isur_cd, txb_com_abbrv);
    $c.stf.showObj(grd_UlyIsuList, false); //엑셀다운로드용 그리드 숨기기

    fn_CheckCond();
    scwin.fn_myFormNmList();
};
